from __future__ import annotations
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent
OUTPUT_EXE = ROOT / "OCodeInstaller.exe"

EMBED_TOKEN = "EMBED_OCODE_HERE"

                                                                  
_OCODE_EXE_B64 = ""

                                                                    
                                                           
_README_B64 = ""
_LICENSE_B64 = ""
import base64 as _b64_init
_README_BYTES = _b64_init.b64decode(_README_B64)
_LICENSE_BYTES = _b64_init.b64decode(_LICENSE_B64)
del _b64_init

                                                                            
_CS_TEMPLATE_B64 = ""

CSPROJ = """<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>WinExe</OutputType>
    <TargetFramework>net8.0-windows</TargetFramework>
    <UseWindowsForms>true</UseWindowsForms>
    <AssemblyName>OCodeInstaller</AssemblyName>
    <RuntimeIdentifier>win-x64</RuntimeIdentifier>
    <SelfContained>true</SelfContained>
    <PublishSingleFile>true</PublishSingleFile>
    <IncludeNativeLibrariesForSelfExtract>true</IncludeNativeLibrariesForSelfExtract>
    <EnableCompressionInSingleFile>true</EnableCompressionInSingleFile>
    <InvariantGlobalization>true</InvariantGlobalization>
    <Nullable>disable</Nullable>
    <ImplicitUsings>disable</ImplicitUsings>
    <EnableWindowsTargeting>true</EnableWindowsTargeting>
  </PropertyGroup>
</Project>
"""


def fail(message: str) -> None:
    print(f"[ERROR] {message}", file=sys.stderr)
    sys.exit(1)


                                                                     
README_TOKEN = "EMBED_README_HERE"

                                                                         
LICENSE_TOKEN = "EMBED_LICENSE_HERE"


def build_cs_source() -> str:
    import base64 as _b64
    template = _b64.b64decode(_CS_TEMPLATE_B64).decode("utf-8")
    if EMBED_TOKEN not in template:
        fail(f"OCodeInstaller.cs template has no {EMBED_TOKEN} placeholder to fill in")
    if README_TOKEN not in template:
        fail(f"OCodeInstaller.cs template has no {README_TOKEN} placeholder to fill in")

                                                                        
                                                                       
                                     
    readme_b64 = _b64.b64encode(_README_BYTES).decode("ascii")
    print(f"[+] Embedding README.md ({len(_README_BYTES)} bytes)")

    print(f"[+] Embedding prebuilt ocode.exe ({len(_OCODE_EXE_B64) // 1024} KB base64)")

                                                                          
    license_b64 = _b64.b64encode(_LICENSE_BYTES).decode("ascii")
    print(f"[+] Embedding LICENSE ({len(_LICENSE_BYTES)} bytes)")
    return template.replace(README_TOKEN, readme_b64).replace(LICENSE_TOKEN, license_b64).replace(EMBED_TOKEN, _OCODE_EXE_B64)


def maybe_rebuild_ocode_exe() -> None:
    """If x86_64-w64-mingw32-g++ (MinGW) is available, recompile ocode.cpp
    into a fresh Windows ocode.exe and replace the embedded _OCODE_EXE_B64
    blob. This is how the v8 HTTP / HTTPS / socket builtins make it into
    the .exe.

    The build tries to link against OpenSSL (-lssl -lcrypto) for HTTPS
    support. If that fails (OpenSSL for MinGW is not installed), it
    falls back to -DOCODE_NO_OPENSSL — plain HTTP still works, https://
    URLs fail with a clear runtime message.

    If MinGW is not installed at all, we keep the existing prebuilt PE
    and print a warning.
    """
    global _OCODE_EXE_B64
    mingw = shutil.which("x86_64-w64-mingw32-g++") or shutil.which("i686-w64-mingw32-g++")
    if not mingw:
        print("[!] MinGW (x86_64-w64-mingw32-g++) not found on PATH.")
        print("    Keeping the existing prebuilt ocode.exe.")
        print("    The .exe will NOT have v8 HTTP / HTTPS / socket builtins until you")
        print("    install MinGW and re-run this script:")
        print("      Debian/Ubuntu:  sudo apt install mingw-w64")
        print("      Alpine:         apk add mingw-w64-gcc")
        print("      macOS:          brew install mingw-w64")
        print()
        return

    print(f"[+] MinGW found: {mingw}")
    print("[*] Recompiling ocode.cpp -> ocode.exe (with v8 HTTP / HTTPS / sockets)...")
    import tempfile, subprocess
    ocode_cpp = ROOT / "ocode.cpp"
    if not ocode_cpp.exists():
        print(f"[!] {ocode_cpp} not found — skipping rebuild.")
        return
    with tempfile.TemporaryDirectory(prefix="ocode_mingw_") as tmp:
        tmp_path = Path(tmp)
        out_exe = tmp_path / "ocode.exe"
                                                                       
                                                                             
                                                                          
                                                                                
        cmd_with_ssl = [mingw, "-std=c++17", "-O2", "-s",
                        "-o", str(out_exe), str(ocode_cpp),
                        "-lssl", "-lcrypto", "-lws2_32", "-static"]
        result = subprocess.run(cmd_with_ssl)
        if result.returncode != 0 or not out_exe.exists():
            print("[!] MinGW + OpenSSL link failed — falling back to no-OpenSSL build.")
            print("    The .exe will support plain HTTP only. https:// URLs will fail")
            print("    at runtime with a clear message.")
            cmd_no_ssl = [mingw, "-std=c++17", "-O2", "-s", "-DOCODE_NO_OPENSSL",
                          "-o", str(out_exe), str(ocode_cpp),
                          "-lws2_32", "-static"]
            result = subprocess.run(cmd_no_ssl)
            if result.returncode != 0 or not out_exe.exists():
                print("[!] MinGW build failed — keeping existing prebuilt ocode.exe.")
                return
        exe_bytes = out_exe.read_bytes()
        import base64 as _b64
        _OCODE_EXE_B64 = _b64.b64encode(exe_bytes).decode("ascii")
        print(f"[+] Built fresh ocode.exe ({len(exe_bytes)} bytes)")
        print(f"    HTTP / HTTPS / socket builtins are now in the .exe.")


def main() -> None:
    print("OCode installer builder  (v8 — HTTP / HTTPS / sockets)")
    print("========================")

    dotnet = shutil.which("dotnet")
    if not dotnet:
        fail(
            "dotnet (the .NET SDK) was not found on PATH.\n"
            "  Alpine:         apk add dotnet8-sdk\n"
            "  Debian/Ubuntu:  apt install dotnet-sdk-8.0\n"
            "  Arch:           pacman -S dotnet-sdk\n"
            "  macOS:          brew install dotnet-sdk\n"
            "  Windows:        https://dotnet.microsoft.com/download"
        )

                                                                                    
                                                                           
                                                           
    maybe_rebuild_ocode_exe()

    cs_source = build_cs_source()

    with tempfile.TemporaryDirectory(prefix="ocode_installer_build_") as tmp:
        tmp_path = Path(tmp)
        (tmp_path / "OCodeInstaller.csproj").write_text(CSPROJ, encoding="utf-8")
        (tmp_path / "OCodeInstaller.cs").write_text(cs_source, encoding="utf-8")

        publish_dir = tmp_path / "out"
        cmd = [
            dotnet, "publish",
            str(tmp_path / "OCodeInstaller.csproj"),
            "-c", "Release",
            "-o", str(publish_dir),
        ]
        print("[*] Building with dotnet (first run downloads the win-x64 desktop")
        print("    runtime pack via NuGet - that's normal and only happens once)...")
        result = subprocess.run(cmd)
        if result.returncode != 0:
            fail("dotnet publish failed - see the output above.")

        built_exe = publish_dir / "OCodeInstaller.exe"
        if not built_exe.exists():
            fail(f"Expected output not found: {built_exe}")

        shutil.copy2(built_exe, OUTPUT_EXE)

    size_mb = OUTPUT_EXE.stat().st_size / (1024 * 1024)
    print(f"[+] Success! Created {OUTPUT_EXE.name} ({size_mb:.1f} MB)")
    print("    Self-contained - runs on any Windows x64 machine, no .NET required there.")


if __name__ == "__main__":
    main()
